{
 "content": "def transform(grid):
    """Combine the paired symbol panels around their center divider."""
    h, w = len(grid), len(grid[0])
    mid = w // 2
    left = [row[:mid] for row in grid]
    right = [row[mid + 1:] for row in grid]
    lc = {v for row in left for v in row}
    rc = {v for row in right for v in row}
    bg_l = max(lc, key=lambda color: sum(v == color for row in left for v in row))
    bg_r = max(rc, key=lambda color: sum(v == color for row in right for v in row))
    # Matching panel backgrounds mean overlay; otherwise the right pattern
    # cuts holes from the left-hand pattern.
    if bg_l == bg_r:
        keep = lambda r, c: left[r][c] != bg_l or right[r][c] != bg_r
    else:
        keep = lambda r, c: left[r][c] != bg_l and right[r][c] == bg_r
    return [[2 if keep(r, c) else 3 for c in range(mid)] for r in range(h)]
"
}

