        bg, fg, rule = 3, 2, lambda a, b: a or b
    elif divider == 6:
        bg, fg, rule = 7, 3, lambda a, b: a and not b
    elif divider == 5:
        bg, fg, rule = 2, 3, lambda a, b: b and not a
    else:
        bg, fg, rule = 3, 2, lambda a, b: a or b
    return [[fg if rule(left[r][c] != bg_left, right[r][c] != bg_right) else bg
             for c in range(mid)] for r in range(h)]
